selector_to_html = {"a[href=\"#vllm\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. vLLM<a class=\"headerlink\" href=\"#vllm\" title=\"Link to this heading\">#</a></h2><p><a class=\"reference external\" href=\"https://github.com/vllm-project/vllm\">vLLM</a>\u662f\u4e00\u4e2a\u541e\u5410\u91cf\u5f88\u9ad8\u7684\u63a8\u7406\u5f15\u64ce\uff0c\n\u5176\u8bbe\u8ba1\u76ee\u6807\u662f\u9ad8\u6548\u5730\u63d0\u4f9b\u5927\u8bed\u8a00\u6a21\u578b\u670d\u52a1\u3002\nvLLM \u652f\u6301 Paged Attention\uff08\u4e00\u79cd\u5e26\u7f13\u5b58\u7684\u6ce8\u610f\u529b\u673a\u5236\uff09\u3001Continuous Batching\n\uff08\u4e00\u79cd\u63d0\u9ad8\u7b97\u529b\u548c\u5e26\u5bbd\u5229\u7528\u7387\u7684\u4efb\u52a1\u961f\u5217\u4f18\u5316\u673a\u5236\uff09\u4ee5\u53ca\u5bf9\u5185\u5b58\u7ba1\u7406\u7684\u4f18\u5316\u3002</p><p><em>FlagGems</em> \u53ef\u4ee5\u88ab\u96c6\u6210\u5230 vLLM \u4e2d\u7528\u6765\u66ff\u6362\u6807\u51c6\u7684 PyTorch \uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">aten</span></code>\uff09\u7b97\u5b50\u4ee5\u53ca\nvLLM \u5185\u90e8\u7684\u5b9a\u5236\u5185\u6838\u3002</p>", "a[href=\"#scope-and-limitations\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2 Scope and Limitations<a class=\"headerlink\" href=\"#scope-and-limitations\" title=\"Link to this heading\">#</a></h3><p>\u2013&gt;</p>", "a[href=\"#vllm-pytorch\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 \u66ff\u6362 vLLM \u4e2d\u7684\u6807\u51c6 PyTorch \u7b97\u5b50<a class=\"headerlink\" href=\"#vllm-pytorch\" title=\"Link to this heading\">#</a></h3><p>\u4e3a\u4e86\u52a0\u901f vLLM \u4e2d\u7528\u5230\u7684\u6807\u51c6\u7684 PyTorch \u7b97\u5b50\uff08\u5982 <code class=\"docutils literal notranslate\"><span class=\"pre\">add</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">masked_fill</span></code> \u7b49\uff09\uff0c\n\u4f60\u53ef\u4ee5\u4f7f\u7528\u4e0e\u5176\u4ed6\u6846\u67b6\u76f8\u540c\u7684\u529e\u6cd5\u3002\n\u901a\u8fc7\u5728\u6a21\u578b\u521d\u59cb\u5316\u6216\u8005\u63a8\u7406\u4efb\u52a1\u542f\u52a8\u4e4b\u524d\u8c03\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems.enable()</span></code>\uff0c\n\u4f60\u53ef\u4ee5\u66ff\u6362\u6389\u6240\u6709\u517c\u5bb9\u7684 PyTorch <code class=\"docutils literal notranslate\"><span class=\"pre\">aten</span></code> \u7b97\u5b50\uff0c\u5305\u62ec\u90a3\u4e9b\u5728 vLLM \u4e2d\u88ab\u95f4\u63a5\u8c03\u7528\u7684\u7b97\u5b50\u3002</p>", "a[href=\"#id4\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.1 \u5efa\u8bae\u7684\u96c6\u6210\u70b9<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h3><p>\u5728 Megatron-LM \u4e2d\u4f7f\u7528 FlagGems \u7684\u6700\u53ef\u9760\u65b9\u5f0f\u662f\u4fee\u6539\u4f4d\u4e8e\n<a class=\"reference external\" href=\"https://github.com/NVIDIA/Megatron-LM/blob/v2.6/megatron/training.py#L347\"><code class=\"docutils literal notranslate\"><span class=\"pre\">megatron/training.py</span></code></a>\n\u6587\u4ef6\u4e2d\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">train_step</span></code> \u51fd\u6570\u3002\u5177\u4f53\u800c\u8a00\uff0c\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems.enable()</span></code> \u751f\u6210\u4e00\u4e2a\u4e0a\u4e0b\u6587\uff0c\n\u5c06\u5bf9 <code class=\"docutils literal notranslate\"><span class=\"pre\">forward_backward_func()</span></code> \u7684\u8c03\u7528\u5c01\u88c5\u5728\u91cc\u9762\u3002\u5982\u4e0b\u9762\u7684\u4ee3\u7801\u6bb5\u6240\u793a\uff1a</p>", "a[href=\"#hugging-face-transformers\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Hugging Face Transformers<a class=\"headerlink\" href=\"#hugging-face-transformers\" title=\"Link to this heading\">#</a></h2><p>\u4e0e Hugging Face \u7684 <a class=\"reference external\" href=\"https://github.com/huggingface/transformers\"><code class=\"docutils literal notranslate\"><span class=\"pre\">transformers</span></code> \u5e93</a>\n\u96c6\u6210\u76f8\u5bf9\u800c\u8a00\u6bd4\u8f83\u7b80\u5355\u76f4\u63a5\u3002\n\u5728\u63a8\u7406\u9636\u6bb5\uff0c\u4f60\u53ef\u4ee5\u542f\u7528 <em>FlagGems</em> \u52a0\u901f\u800c\u4e0d\u5fc5\u66f4\u6539\u6a21\u578b\u6216\u8005\u5206\u8bcd\u5668\u7684\u903b\u8f91\u3002</p><p>\u4e0b\u9762\u662f\u4e00\u4e2a\u9ad8\u5ea6\u7b80\u5316\u7684\u4f8b\u5b50\uff1a</p>", "a[href=\"#megatron-lm\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Megatron-LM<a class=\"headerlink\" href=\"#megatron-lm\" title=\"Link to this heading\">#</a></h2><p><a class=\"reference external\" href=\"https://github.com/NVIDIA/Megatron-LM\">Megatron-LM</a> \u662f\u4e00\u4e2a\u9488\u5bf9\u5927\u89c4\u6a21\u8bed\u8a00\u6a21\u578b\u7684\u9884\u8bad\u7ec3\u3001\n\u8c03\u4f18\u4f5c\u4e86\u9ad8\u5ea6\u4f18\u5316\u7684\u5e8a\u67b6\u3002\u7531\u4e8e\u6846\u67b6\u5185\u90e8\u7d27\u8026\u5408\u4e86\u4e00\u4e9b\u5b9a\u5236\u7684\u8bad\u7ec3\u56de\u8def\u548c\u5185\u90e8\u5de5\u5177\uff0c\n\u5c06 <em>FlagGems</em> \u96c6\u6210\u5230 Megatron-LM \u9700\u8981\u4e00\u4e9b\u66f4\u6709\u9488\u5bf9\u6027\u7684\u64cd\u4f5c\u3002</p><p>\u7531\u4e8e Megatron-LM \u4e2d\u7684\u8bad\u7ec3\u56de\u8def\u4e0e\u5176\u5206\u5e03\u5f0f\u6570\u636e\u52a0\u8f7d\u3001\u68af\u5ea6\u7d2f\u79ef\u3001\u6d41\u6c34\u7ebf\u5e76\u884c\u7d27\u5bc6\u7ed1\u5b9a\uff0c\n\u6211\u4eec\u5efa\u8bae\u4ec5\u5bf9\u5176\u524d\u5411\u548c\u53cd\u5411\u8ba1\u7b97\u9636\u6bb5\u5e94\u7528 <em>FlagGems</em> \u7b97\u5b50\u52a0\u901f\u3002</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 \u66ff\u6362\u7279\u5b9a\u4e8e vLLM \u7684\u5b9a\u5236\u7b97\u5b50<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>\u4e3a\u4e86\u8fdb\u4e00\u6b65\u4f18\u5316 vLLM \u5185\u90e8\u7684\u5185\u6838\uff0c<em>FlagGems</em> \u63d0\u4f9b\u4e86\u4e00\u4e2a\u989d\u5916\u7684 API\uff1a</p>", "a[href=\"#id5\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2 \u8303\u56f4\u4e0e\u5c40\u9650\u6027<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h3><p>\u5c3d\u7ba1\u5728\u5927\u591a\u6570\u6846\u67b6\u4e2d\uff0c\u8c03\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems.enable()</span></code> \u5c31\u8db3\u591f\u4e86\uff0c\u6211\u4eec\u8fd8\u662f\u53d1\u73b0\u5982\u679c\u5728\nMegatron-LM \u6d41\u6c34\u7ebf\u7684\u65e9\u671f\u9636\u6bb5\uff08\u5c24\u5176\u662f\u6570\u636e\u52a0\u8f7d\u9636\u6bb5\uff09\u542f\u7528\u52a0\u901f\u7b97\u5b50\u7684\u8bdd\uff0c\n\u53ef\u80fd\u4f1a\u4ea7\u751f\u4e00\u4e9b\u610f\u5916\u7684\u884c\u4e3a\u3002\n\u4e3a\u4e86\u786e\u4fdd\u7cfb\u7edf\u7a33\u5b9a\u6027\u4e0d\u53d7\u5f71\u54cd\uff0c\u6211\u4eec\u5efa\u8bae\u7528\u4e0a\u4e0b\u6587\u7ba1\u7406\u5668\uff08context manager\uff09\u7684\u65b9\u5f0f\u6765\u8c03\u7528\n<code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems.use_gems()</span></code>\uff0c\u5e76\u4e14\u4ec5\u5e94\u7528\u5230\u5176\u8ba1\u7b97\u9636\u6bb5\u3002</p><p>\u5982\u679c\u4f60\u5e0c\u671b\u9488\u5bf9\u66f4\u5927\u8303\u56f4\u7684\u7ec4\u4ef6\uff08\u4f8b\u5982\u4f18\u5316\u5668\u3001\u9884\u5904\u7406\u903b\u8f91\uff09\u8fdb\u884c\u52a0\u901f\uff0c\n\u4f60\u53ef\u4ee5\u5c1d\u8bd5\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems.enable()</span></code> \u5728\u5168\u5c40\u4f5c\u7528\u57df\u542f\u7528\u52a0\u901f\u7b97\u5b50\u3002\n\u4e0d\u8fc7\u8fd9\u79cd\u65b9\u5f0f\u6ca1\u6709\u7ecf\u8fc7\u5f7b\u5e95\u7684\u6d4b\u8bd5\uff0c\u53ef\u80fd\u9700\u8981\u57fa\u4e8e\u4f60\u6240\u4f7f\u7528\u7684 Megatron-LM\n\u7248\u672c\u5f00\u5c55\u4e00\u4e9b\u989d\u5916\u7684\u9a8c\u8bc1\u5de5\u4f5c\u3002</p>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.3 \u5b8c\u6574\u7684\u793a\u4f8b<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../contribution/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u6982\u8ff0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u5728\u62c9\u53d6\u8bf7\u6c42\uff08Pull Request\uff09\u4e2d\uff0c\u8d21\u732e\u8005\u5e94\u8be5\u5c31\u6240\u63d0\u8bae\u7684\u53d8\u66f4\u7ed9\u51fa\u63cf\u8ff0\uff0c\u5305\u62ec\u53d8\u66f4\u7684\u539f\u56e0\u3002\n\u5728\u9700\u8981\u7684\u60c5\u51b5\u4e0b\uff0c\u8bf7\u4e00\u5e76\u63d0\u4ea4\u5355\u5143\u6d4b\u8bd5\u7528\u4f8b\u3002\n\u5728\u62c9\u53d6\u8bf7\u6c42\u88ab\u6700\u7ec8\u5408\u5165\u4e4b\u524d\uff0c\u9700\u8981<strong>\u4e00\u4e2a\u9879\u76ee\u6210\u5458</strong>\u7684\u6279\u51c6\u3002\n\u6b64\u5916\uff0c\u8fd9\u7c7b\u62c9\u53d6\u8bf7\u6c42\u4e5f\u5fc5\u987b\u901a\u8fc7\u6301\u7eed\u96c6\u6210\uff08Continuous Integration\uff0cCI\uff09\u6d4b\u8bd5\u3002</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0e\u5e38\u7528\u6846\u67b6\u7684\u96c6\u6210<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u4e3a\u4e86\u5e2e\u52a9\u7528\u6237\u5c06 <em>FlagGems</em> \u96c6\u6210\u5230\u771f\u5b9e\u4e16\u754c\u7684\u4f7f\u7528\u573a\u666f\u4e2d\uff0c\u6211\u4eec\u63d0\u4f9b\u4e00\u4e9b\u793a\u4f8b\uff0c\n\u5c55\u793a\u5982\u4f55\u4e0e\u67d0\u4e9b\u88ab\u5e7f\u6cdb\u4f7f\u7528\u7684\u6df1\u5ea6\u5b66\u4e60\u6846\u67b6\u96c6\u6210\u3002\n\u8fd9\u4e9b\u96c6\u6210\u9700\u8981\u6781\u5c11\u7684\u4ee3\u7801\u53d8\u66f4\uff0c\u80fd\u591f\u4fdd\u7559\u539f\u6765\u7684\u5de5\u4f5c\u6d41\u7ed3\u6784\u3002</p><p>\u5982\u679c\u4f60\u5bf9\u5b8c\u6574\u7684\u793a\u4f8b\u611f\u5174\u8da3\uff0c\u53ef\u4ee5\u53c2\u9605\u6e90\u4ee3\u7801\u4ed3\u5e93\u4e2d\u7684\n<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems/tree/master/examples\"><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/</span></code></a>\n\u76ee\u5f55\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
